Validate the title in the route itself and return 400 before touching SQLite.

```js
router.post("/", (req, res) => {
  const title = typeof req.body.title === "string" ? req.body.title.trim() : ""
  if (title.length === 0) return res.status(400).json({ error: "title is required" })
  const result = db.prepare("INSERT INTO tasks (title) VALUES (?)").run(title)
  res.status(201).json({ id: result.lastInsertRowid, title })
})
```

Keep the hook responsible for the request and throw on failure so the form decides what to show.

```ts
import { useState } from "react"

export interface User {
  email: string
}

export function useAuth() {
  const [user, setUser] = useState<User | null>(null)

  async function login(email: string, password: string) {
    const response = await fetch("/api/login", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ email, password }),
    })
    if (!response.ok) throw new Error("Invalid credentials")
    setUser((await response.json()) as User)
  }

  return { user, setUser, login }
}
```

